import { EventEmitter } from "events";
import { ethers } from "ethers";
import { JsonRpcProvider } from "@ethersproject/providers";
import { getClaim, ClaimHonestState } from "../utils/claim";
import { getBlocksAndCheckFinality, resolveSettledReadBlocks } from "../utils/arbToEthState";
import { getLastClaimedEpoch } from "../utils/graphQueries";
import { BotEvents } from "../utils/botEvents";
import { ClaimStruct } from "../../../contracts/typechain-types/arbitrumToEth/VeaInboxArbToEth";
import { ITransactionHandler, IDevnetTransactionHandler, getTransactionHandler } from "../utils/transactionHandlers";
import { Network } from "../consts/bridgeRoutes";
import { getLookbackFloorBlock } from "../utils/epochHandler";
import { findLatestLog } from "../utils/logScanner";
interface CheckAndClaimParams {
  chainId: number;
  network: Network;
  claim: ClaimStruct | null;
  epochPeriod: number;
  epoch: number;
  veaInbox: any;
  veaInboxProvider: JsonRpcProvider;
  veaOutbox: any;
  veaOutboxProvider: JsonRpcProvider;
  veaRouterProvider?: JsonRpcProvider;
  transactionHandler: ITransactionHandler | null;
  emitter: EventEmitter;
  fetchClaim?: typeof getClaim;
  fetchLatestClaimedEpoch?: typeof getLastClaimedEpoch;
  fetchTransactionHandler?: typeof getTransactionHandler;
  fetchBlocksAndCheckFinality?: typeof getBlocksAndCheckFinality;
  fetchSettledReadBlocks?: typeof resolveSettledReadBlocks;
  now?: number;
}

async function checkAndClaim({
  chainId,
  network,
  claim,
  epoch,
  epochPeriod,
  veaInbox,
  veaInboxProvider,
  veaOutbox,
  veaOutboxProvider,
  transactionHandler,
  emitter,
  veaRouterProvider,
  fetchLatestClaimedEpoch = getLastClaimedEpoch,
  fetchTransactionHandler = getTransactionHandler,
  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
  fetchSettledReadBlocks = resolveSettledReadBlocks,
  now = Date.now(),
}: CheckAndClaimParams) {
  let outboxStateRoot = await veaOutbox.stateRoot();
  const claimAbleEpoch = Math.floor(now / (1000 * epochPeriod)) - 1;
  if (!transactionHandler) {
    const TransactionHandler = fetchTransactionHandler(chainId, network);
    transactionHandler = new TransactionHandler({
      chainId,
      network,
      epoch,
      veaInbox,
      veaOutbox,
      veaInboxProvider,
      veaOutboxProvider,
      emitter,
      claim,
    });
  } else {
    transactionHandler.claim = claim;
  }
  if (network == Network.DEVNET) {
    return makeClaimDevnet(
      epoch,
      claim,
      outboxStateRoot,
      transactionHandler as IDevnetTransactionHandler,
      veaInbox,
      emitter
    );
  } else if (claim == null && epoch == claimAbleEpoch) {
    const queryRpc = veaRouterProvider ?? veaOutboxProvider;
    return makeClaim(
      chainId,
      epoch,
      epochPeriod,
      transactionHandler,
      veaInbox,
      veaOutbox,
      queryRpc,
      veaOutboxProvider,
      emitter,
      fetchLatestClaimedEpoch,
      fetchBlocksAndCheckFinality,
      fetchSettledReadBlocks
    );
  } else if (claim != null) {
    return verifyClaim(transactionHandler, claim, veaOutboxProvider);
  } else {
    emitter.emit(BotEvents.CLAIM_EPOCH_PASSED, epoch);
  }
  return null;
}

async function makeClaimDevnet(
  epoch: number,
  claim: ClaimStruct | null,
  outboxStateRoot: string,
  transactionHandler: IDevnetTransactionHandler,
  veaInbox: any,
  emitter: EventEmitter
): Promise<IDevnetTransactionHandler | null> {
  if (claim == null) {
    const [savedSnapshot] = await Promise.all([veaInbox.snapshots(epoch)]);

    const newMessagesToBridge = savedSnapshot != outboxStateRoot && savedSnapshot != ethers.ZeroHash;
    if (newMessagesToBridge && savedSnapshot != ethers.ZeroHash) {
      await transactionHandler.devnetAdvanceState(savedSnapshot);
      return transactionHandler;
    }
  }
  emitter.emit(BotEvents.NO_CLAIM_REQUIRED, epoch);
  return null;
}

async function makeClaim(
  chainId: number,
  epoch: number,
  epochPeriod: number,
  transactionHandler: ITransactionHandler,
  veaInbox: any,
  veaOutbox: any,
  queryRpc: JsonRpcProvider,
  veaOutboxProvider: JsonRpcProvider,
  emitter: EventEmitter,
  fetchLatestClaimedEpoch: typeof getLastClaimedEpoch = getLastClaimedEpoch,
  fetchBlocksAndCheckFinality: typeof getBlocksAndCheckFinality,
  fetchSettledReadBlocks: typeof resolveSettledReadBlocks = resolveSettledReadBlocks
): Promise<ITransactionHandler | null> {
  // Claiming stakes a deposit on the snapshot we are about to read, so resolve
  // the settled blocks first and read only at them.
  const settledBlocks = await fetchSettledReadBlocks({
    inboxProvider: transactionHandler.veaInboxProvider,
    outboxProvider: queryRpc,
    outboxChainProvider: veaOutboxProvider,
    epoch,
    epochPeriod,
    emitter: emitter as any,
    fetchBlocksAndCheckFinality,
  });
  if (!settledBlocks) return null;

  const savedSnapshot = await veaInbox.snapshots(epoch, { blockTag: settledBlocks.inboxBlock });
  if (savedSnapshot == ethers.ZeroHash) {
    return null;
  }
  const outboxStateRoot = await veaOutbox.stateRoot({ blockTag: settledBlocks.outboxBlock });
  let lastClaimedStateroot: string | null = null;
  try {
    const [floorBlock, headBlock] = await Promise.all([
      getLookbackFloorBlock({ provider: veaOutboxProvider, chainId, epochPeriod }),
      veaOutboxProvider.getBlock("finalized"),
    ]);
    const lastClaimLog = await findLatestLog({
      contract: veaOutbox,
      filter: veaOutbox.filters.Claimed(),
      fromBlock: floorBlock,
      toBlock: headBlock.number,
    });
    lastClaimedStateroot = lastClaimLog?.data ?? null;
  } catch {
    const claimData = await fetchLatestClaimedEpoch(veaOutbox.target, chainId);
    lastClaimedStateroot = claimData ? claimData.stateRoot : ethers.ZeroHash;
  }
  if (lastClaimedStateroot == null) {
    return null;
  }
  const newMessagesToBridge = savedSnapshot != outboxStateRoot && savedSnapshot != lastClaimedStateroot;
  if (newMessagesToBridge) {
    await transactionHandler.makeClaim(savedSnapshot);
    return transactionHandler;
  }
  return null;
}

async function verifyClaim(
  transactionHandler: ITransactionHandler,
  claim: ClaimStruct,
  veaOutboxProvider: JsonRpcProvider
) {
  if (claim.honest == ClaimHonestState.CLAIMER) {
    await transactionHandler.withdrawClaimDeposit();
    return transactionHandler;
  } else if (claim.honest == ClaimHonestState.NONE) {
    const finalizedOutboxBlock = await veaOutboxProvider.getBlock("finalized");
    if (claim.challenger != ethers.ZeroAddress) {
      return transactionHandler;
    }
    if (claim.timestampVerification == 0) {
      await transactionHandler.startVerification(finalizedOutboxBlock.timestamp);
    } else {
      await transactionHandler.verifySnapshot(finalizedOutboxBlock.timestamp);
    }
    return transactionHandler;
  }
}

export { checkAndClaim, CheckAndClaimParams };

import { JsonRpcProvider } from "@ethersproject/providers";
import { ethers } from "ethers";
import { ITransactionHandler, getTransactionHandler } from "../utils/transactionHandlers";
import { getClaim, getClaimResolveState } from "../utils/claim";
import { defaultEmitter } from "../utils/emitter";
import { BotEvents } from "../utils/botEvents";
import { getBlocksAndCheckFinality, resolveSettledReadBlocks } from "../utils/arbToEthState";
import { Network } from "../consts/bridgeRoutes";
import { ClaimStruct } from "../../../contracts/typechain-types/arbitrumToEth/VeaInboxArbToEth";

export interface ChallengeAndResolveClaimParams {
  chainId: number;
  claim: ClaimStruct;
  epoch: number;
  epochPeriod: number;
  veaInbox: any;
  veaInboxProvider: JsonRpcProvider;
  veaOutboxProvider: JsonRpcProvider;
  veaRouterProvider?: JsonRpcProvider;
  veaOutbox: any;
  transactionHandler: ITransactionHandler | null;
  emitter?: typeof defaultEmitter;
  fetchClaim?: typeof getClaim;
  fetchClaimResolveState?: typeof getClaimResolveState;
  fetchBlocksAndCheckFinality?: typeof getBlocksAndCheckFinality;
  fetchSettledReadBlocks?: typeof resolveSettledReadBlocks;
  fetchTransactionHandler?: typeof getTransactionHandler;
}

export async function challengeAndResolveClaim({
  chainId,
  claim,
  epoch,
  epochPeriod,
  veaInbox,
  veaInboxProvider,
  veaOutboxProvider,
  veaOutbox,
  transactionHandler,
  emitter = defaultEmitter,
  veaRouterProvider,
  fetchClaimResolveState = getClaimResolveState,
  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
  fetchSettledReadBlocks = resolveSettledReadBlocks,
  fetchTransactionHandler = getTransactionHandler,
}: ChallengeAndResolveClaimParams): Promise<ITransactionHandler | null> {
  if (!claim) {
    emitter.emit(BotEvents.NO_CLAIM, epoch);
    return null;
  }
  const l1Provider = veaRouterProvider ?? veaOutboxProvider;
  // Resolve the blocks this epoch can be read as settled at before reading
  // anything: a challenge stakes a deposit on the value we are about to read.
  // outboxProvider anchors Arbitrum's finality check (L1/router). Only
  // settledBlocks.inboxBlock is consumed here, so the outbox chain's own
  // finalized block is not requested.
  const settledBlocks = await fetchSettledReadBlocks({
    inboxProvider: veaInboxProvider,
    outboxProvider: l1Provider,
    epoch,
    epochPeriod,
    emitter,
    fetchBlocksAndCheckFinality,
  });
  if (!settledBlocks) return null;
  const ethBlockTag = "finalized";

  if (!transactionHandler) {
    const TransactionHandler = fetchTransactionHandler(chainId, Network.TESTNET);
    transactionHandler = new TransactionHandler({
      chainId,
      network: Network.TESTNET, // Hardcoded as TESTNET & MAINNET have same contracts
      epoch,
      veaInbox,
      veaOutbox,
      veaInboxProvider,
      veaOutboxProvider,
      veaRouterProvider,
      emitter,
      claim,
    });
  } else {
    transactionHandler.claim = claim;
  }
  // If claim is already resolved, nothing to do
  if (claim.honest !== 0) {
    emitter.emit(BotEvents.CLAIM_ALREADY_RESOLVED, epoch);
    if (claim.honest === 2) {
      await transactionHandler.withdrawChallengeDeposit();
      return transactionHandler;
    }
    return null;
  }

  const { challenged, toRelay } = await challengeAndCheckRelay({
    veaInbox,
    epoch,
    claim,
    transactionHandler,
    arbitrumBlockNumber: settledBlocks.inboxBlock,
  });
  if (!toRelay && !challenged) {
    return null;
  } else if (challenged && !toRelay) {
    return transactionHandler;
  }
  await handleResolveFlow({
    chainId,
    epoch,
    epochPeriod,
    claim,
    veaInbox,
    veaInboxProvider,
    veaOutbox,
    veaOutboxProvider,
    veaRouterProvider,
    ethBlockTag,
    transactionHandler,
    fetchClaimResolveState,
  });

  return transactionHandler;
}

interface ChallengeAndCheckRelayParams {
  veaInbox: any;
  epoch: number;
  claim: ClaimStruct;
  transactionHandler: ITransactionHandler;
  arbitrumBlockNumber: number;
}
async function challengeAndCheckRelay({
  veaInbox,
  epoch,
  claim,
  transactionHandler,
  arbitrumBlockNumber,
}: ChallengeAndCheckRelayParams): Promise<{ challenged: boolean; toRelay: boolean }> {
  const onChainSnapshot = await veaInbox.snapshots(epoch, { blockTag: arbitrumBlockNumber });
  const isNotChallenged = claim.challenger === ethers.ZeroAddress;
  const challengeAndRelayState = {
    challenged: false,
    toRelay: false,
  };
  if (onChainSnapshot !== claim.stateRoot && isNotChallenged) {
    await transactionHandler.challengeClaim();
    challengeAndRelayState.challenged = true;
  }
  if (!isNotChallenged) {
    return { challenged: true, toRelay: true };
  }
  return challengeAndRelayState;
}

interface ResolveFlowParams {
  chainId: number;
  epoch: number;
  epochPeriod: number;
  claim: ClaimStruct;
  veaInbox: any;
  veaInboxProvider: JsonRpcProvider;
  veaOutbox: any;
  veaOutboxProvider: JsonRpcProvider;
  veaRouterProvider?: JsonRpcProvider;
  ethBlockTag: "latest" | "finalized";
  transactionHandler: ITransactionHandler;
  fetchClaimResolveState: typeof getClaimResolveState;
}
async function handleResolveFlow({
  chainId,
  epoch,
  epochPeriod,
  claim,
  veaInbox,
  veaInboxProvider,
  veaOutbox,
  veaOutboxProvider,
  veaRouterProvider,
  ethBlockTag,
  transactionHandler,
  fetchClaimResolveState,
}: ResolveFlowParams): Promise<void> {
  const claimResolveState = await fetchClaimResolveState({
    chainId,
    veaInbox,
    veaInboxProvider,
    veaOutbox,
    veaOutboxProvider,
    veaRouterProvider,
    epoch,
    epochPeriod,
    headBlockTag: ethBlockTag,
  });

  if (!claimResolveState.sendSnapshot.status) {
    await transactionHandler.sendSnapshot();
    return;
  }
  const execStatus = claimResolveState.execution.status;
  if (execStatus === 1) {
    await transactionHandler.resolveChallengedClaim(claimResolveState.sendSnapshot.txHash);
  } else if (execStatus === 2 && claim.honest === 2) {
    await transactionHandler.withdrawChallengeDeposit();
  }
}

import { JsonRpcProvider, Block } from "@ethersproject/providers";
import { SequencerInbox } from "@arbitrum/sdk/dist/lib/abi/SequencerInbox";
import { NodeInterface__factory } from "@arbitrum/sdk/dist/lib/abi/factories/NodeInterface__factory";
import { NodeInterface } from "@arbitrum/sdk/dist/lib/abi/NodeInterface";
import { NODE_INTERFACE_ADDRESS } from "@arbitrum/sdk/dist/lib/dataEntities/constants";
import { getArbitrumNetwork } from "@arbitrum/sdk";
import { SequencerInbox__factory } from "@arbitrum/sdk/dist/lib/abi/factories/SequencerInbox__factory";
import { defaultEmitter } from "../utils/emitter";
import { BotEvents } from "../utils/botEvents";
import { findFirstLog } from "./logScanner";

// https://github.com/prysmaticlabs/prysm/blob/493905ee9e33a64293b66823e69704f012b39627/config/params/mainnet_config.go#L103
const slotsPerEpochEth = 32;
const secondsPerSlotEth = 12;

export interface SettledReadBlocks {
  inboxBlock: number;
  outboxBlock: number;
}

export interface ResolveSettledReadBlocksParams {
  inboxProvider: JsonRpcProvider;
  // L1/router provider used only to anchor Arbitrum's finality (that the
  // Arbitrum "finalized" block is posted in a finalized L1 batch). For routes
  // where the outbox does not live on this chain (e.g. arbToGnosis, where
  // this is Sepolia but the outbox is on Chiado), it is NOT a valid source for
  // outbox-chain block numbers.
  outboxProvider: JsonRpcProvider;
  // The actual outbox chain's provider, used to read its own "finalized"
  // block. Defaults to the L1/router finalized block above for routes where
  // the outbox lives on that same chain (arbToEth).
  outboxChainProvider?: JsonRpcProvider;
  epoch: number;
  epochPeriod: number;
  emitter?: typeof defaultEmitter;
  fetchBlocksAndCheckFinality?: typeof getBlocksAndCheckFinality;
}

/**
 * Resolve the blocks at which this epoch's state can be read as settled.
 *
 * Two conditions have to hold before a read can be staked on:
 *
 *  - the block cannot be reorged away, so we anchor to the `finalized` head on
 *    both chains;
 *  - the block must sit at or after `(epoch + 1) * epochPeriod`, because
 *    `snapshots[epoch]` is still being written during epoch E.
 *
 * When either fails the epoch is simply not decidable yet: callers skip it and
 * try again next cycle rather than acting on unsettled state.
 *
 * @returns The blocks to pin reads to, or null if the epoch is not yet decidable
 */
export const resolveSettledReadBlocks = async ({
  inboxProvider,
  outboxProvider,
  outboxChainProvider,
  epoch,
  epochPeriod,
  emitter = defaultEmitter,
  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
}: ResolveSettledReadBlocksParams): Promise<SettledReadBlocks | null> => {
  const finality = await fetchBlocksAndCheckFinality(outboxProvider, inboxProvider, epoch, epochPeriod, emitter);
  // Checked before destructuring: this returns undefined on an unresolvable
  // chain state, and destructuring that throws past every caller's guard.
  if (!finality) {
    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
    return null;
  }
  const [inboxFinalized, l1Finalized, finalityIssueFlagArb, finalityIssueFlagEth] = finality;
  if (finalityIssueFlagArb || finalityIssueFlagEth) {
    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
    return null;
  }

  const epochBoundary = (epoch + 1) * epochPeriod;
  if (inboxFinalized.timestamp < epochBoundary) {
    emitter.emit(BotEvents.EPOCH_NOT_SETTLED, epoch, inboxFinalized.timestamp, epochBoundary);
    return null;
  }

  // The outbox contract is not necessarily on the L1/router chain used above
  // to anchor Arbitrum's finality, so its finalized block must be read
  // separately from the chain it actually lives on.
  const outboxFinalized = outboxChainProvider ? await outboxChainProvider.getBlock("finalized") : l1Finalized;

  return { inboxBlock: inboxFinalized.number, outboxBlock: outboxFinalized.number };
};

/**
 * The sequencer's maximum backdating window, in seconds.
 *
 * `maxTimeVariation()` returns four values -- [delayBlocks, futureBlocks,
 * delaySeconds, futureSeconds] -- so coercing the whole result yields NaN, which
 * then silently poisons every block range derived from it.
 *
 * @returns delaySeconds from the sequencer inbox
 */
const getSequencerDelaySeconds = async (sequencer: SequencerInbox): Promise<number> => {
  const { delaySeconds } = await sequencer.maxTimeVariation();
  return Number(delaySeconds);
};

/**
 * This function checks the finality of the blocks on Arbitrum and Ethereum.
 * It returns the latest/finalized block on Arbitrum(found on Ethereum) and Ethereum and a flag indicating if there is a finality issue on Ethereum.
 *
 * @param EthProvider Ethereum provider
 * @param ArbProvider Arbitrum provider
 * @param veaEpoch epoch number of the claim to be fetched
 * @param veaEpochPeriod epoch period of the claim to be fetched
 *
 * @returns [Arbitrum block, Ethereum block, finalityIssueFlagArb, finalityIssueFlagEth]
 * */
const getBlocksAndCheckFinality = async (
  EthProvider: JsonRpcProvider,
  ArbProvider: JsonRpcProvider,
  veaEpoch: number,
  veaEpochPeriod: number,
  emitter: typeof defaultEmitter
): Promise<[Block, Block, boolean, boolean] | undefined> => {
  const currentEpoch = Math.floor(Date.now() / 1000 / veaEpochPeriod);

  const l2Network = await getArbitrumNetwork(ArbProvider);
  const sequencer = SequencerInbox__factory.connect(l2Network.ethBridge.sequencerInbox, EthProvider);
  const maxDelaySeconds = await getSequencerDelaySeconds(sequencer);
  const blockFinalizedArb = (await ArbProvider.getBlock("finalized")) as Block;
  const blockFinalizedEth = (await EthProvider.getBlock("finalized")) as Block;
  if (
    currentEpoch - veaEpoch > 2 &&
    blockFinalizedArb.timestamp > veaEpoch * veaEpochPeriod &&
    blockFinalizedEth.timestamp > veaEpoch * veaEpochPeriod
  ) {
    return [blockFinalizedArb, blockFinalizedEth, false, false];
  }
  const finalityBuffer = 300; // 5 minutes, allows for network delays
  const maxFinalityTimeSecondsEth = slotsPerEpochEth * 2 * secondsPerSlotEth; // finalization after 2 justified epochs

  let finalityIssueFlagArb = false;
  let finalityIssueFlagEth = false;

  // check latest arb block to see if there are any sequencer issues
  let blockLatestArb = (await ArbProvider.getBlock("latest")) as Block;

  const maxDelayInSeconds = 7 * 24 * 60 * 60; // 7 days
  let blockoldArb = (await ArbProvider.getBlock(blockLatestArb.number - 100)) as Block;
  const arbAverageBlockTime = (blockLatestArb.timestamp - blockoldArb.timestamp) / 100;
  const fromBlockArbFinalized = blockFinalizedArb.number - Math.ceil(maxDelayInSeconds / arbAverageBlockTime);
  // to performantly query the sequencerInbox's SequencerBatchDelivered event on Eth, we limit the block range
  // we use the heuristic that. delta blocknumber <= delta timestamp / secondsPerSlot
  // Arb: -----------x                   <-- Finalized
  //                 ||
  //                 \/
  // Eth: -------------------------x     <-- Finalized
  //            /\
  //            ||<---------------->     <-- Math.floor((timeDiffBlockFinalizedArbL1 + maxDelaySeconds) / secondsPerSlotEth)
  //         fromBlockEth

  const timeDiffBlockFinalizedArbL1 = blockFinalizedEth.timestamp - blockFinalizedArb.timestamp;
  const fromBlockEthFinalized =
    blockFinalizedEth.number - Math.floor((timeDiffBlockFinalizedArbL1 + maxDelaySeconds) / secondsPerSlotEth);

  let blockFinalizedArbToL1Block = await ArbBlockToL1Block(
    ArbProvider,
    sequencer,
    blockFinalizedArb,
    fromBlockEthFinalized,
    fromBlockArbFinalized,
    false
  );

  if (!blockFinalizedArbToL1Block) {
    emitter.emit(BotEvents.FINALITY_ERROR, "Arbitrum finalized block is not found on L1.");
    finalityIssueFlagArb = true;
  } else if (Math.abs(blockFinalizedArbToL1Block[0].timestamp - blockFinalizedArb.timestamp) > 1800) {
    // The L2 timestamp is drifted from the L1 timestamp in which the L2 block is posted.
    emitter.emit(BotEvents.FINALITY_ERROR, "Finalized L2 block time is more than 30 min drifted from L1 clock.");
  }

  // blockLatestArbToL1Block[0] is the L1 block, blockLatestArbToL1Block[1] is the L2 block (fallsback on latest L2 block if L2 block is not found on L1)
  let blockLatestArbToL1Block = await ArbBlockToL1Block(
    ArbProvider,
    sequencer,
    blockLatestArb,
    fromBlockEthFinalized,
    fromBlockArbFinalized,
    true
  );

  if (finalityIssueFlagArb && !blockLatestArbToL1Block) {
    emitter.emit(BotEvents.FINALITY_ERROR, "Arbitrum latest block is not found on L1.");
    // this means some issue in the arbitrum node implementation (very bad)
    return undefined;
  }

  // is blockLatestArb is not found on L1, ArbBlockToL1Block fallsback on the latest L2 block found on L1
  if (blockLatestArbToL1Block[1] != blockLatestArb.number) {
    blockLatestArb = (await ArbProvider.getBlock(blockLatestArbToL1Block[1])) as Block;
  }

  // ETH POS assumes synchronized clocks
  // using local time as a proxy for true "latest" L1 time
  const localTimeSeconds = Math.floor(Date.now() / 1000);

  // The sequencer is completely offline
  if (localTimeSeconds - blockLatestArbToL1Block[0].timestamp > 1800) {
    emitter.emit(
      BotEvents.FINALITY_ERROR,
      "Arbitrum sequencer is offline (from L1 'latest' POV) for atleast 30 minutes."
    );
    finalityIssueFlagArb = true;
  }

  // The L2 timestamp is drifted from the L1 timestamp in which the L2 block is posted.
  // Not necessarily a problem, but we should know about it
  if (Math.abs(blockLatestArbToL1Block[0].timestamp - blockLatestArb.timestamp) > 1800) {
    emitter.emit(
      BotEvents.FINALITY_ERROR,
      `Latest L2 block time is more than 30 min drifted from L1 clock. \n L2 block time: ${blockLatestArb.timestamp}, L1 block time: ${blockLatestArbToL1Block[0].timestamp}, L2 block number: ${blockLatestArb.number}`
    );
  }

  // Note: Using last finalized block as a proxy for the latest finalized epoch
  // Using a BeaconChain RPC would be more accurate
  if (localTimeSeconds - blockFinalizedEth.timestamp > maxFinalityTimeSecondsEth + finalityBuffer) {
    emitter.emit(BotEvents.FINALITY_ERROR, "Ethereum mainnet is experiencing finalization issues.");
    finalityIssueFlagEth = true;
  }

  if (blockFinalizedEth.number < blockFinalizedArbToL1Block[0].number) {
    emitter.emit(
      BotEvents.FINALITY_ERROR,
      "Arbitrum 'finalized' block is posted in an L1 block which is not finalized. Arbitrum node is out of sync with L1 node. It's recommended to use the same L1 RPC as the L1 node used by the Arbitrum node."
    );
    finalityIssueFlagArb = true;
  }
  // Always the finalized block: it is the one proven above to sit in a batch
  // delivered by a finalized L1 block. blockLatestArb carries the unfinalized
  // tail, and callers stake deposits on whatever is returned here.
  return [blockFinalizedArb, blockFinalizedEth, finalityIssueFlagArb, finalityIssueFlagEth];
};

/**
 *
 * This function finds the corresponding L1(Eth) block for a given L2(Arb) block.
 *
 * @param L2Provider Arbitrum provider
 * @param sequencer Arbitrum sequencerInbox
 * @param L2Block L2 block
 * @param fromBlockEth from block number on Eth
 * @param fromArbBlock from block number on Arb
 * @param fallbackLatest fallback to latest L2 block if the L2 block is not found on L1
 *
 * @returns [L1Block, L2BlockNumberFallback]
 */

const ArbBlockToL1Block = async (
  L2Provider: JsonRpcProvider,
  sequencer: SequencerInbox,
  L2Block: Block,
  fromBlockEth: number,
  fromArbBlock: number,
  fallbackLatest: boolean
): Promise<[Block, number] | undefined> => {
  const nodeInterface = NodeInterface__factory.connect(NODE_INTERFACE_ADDRESS, L2Provider);

  let latestL2batchOnEth: number;
  let latestL2BlockNumberOnEth: number;
  let result = (await nodeInterface.functions
    .findBatchContainingBlock(L2Block.number, { blockTag: "latest" })
    .catch(async (e) => {
      // If the L2Block is the latest ArbBlock this will always throw, so we fallback to finding the latest L2 batch and block
      if (!fallbackLatest) {
        return undefined;
      } else {
        [latestL2batchOnEth, latestL2BlockNumberOnEth] = await findLatestL2BatchAndBlock(
          nodeInterface,
          fromArbBlock,
          L2Block.number
        );
      }
    })) as any;

  const batch = result?.batch?.toNumber() ?? latestL2batchOnEth;
  const L2BlockNumberFallback = latestL2BlockNumberOnEth ?? L2Block.number;
  /**
   * We use the batch number to query the L1 sequencerInbox's SequencerBatchDelivered event
   * then, we get its emitted transaction hash.
   */
  const emittedEvent = await findFirstLog({
    contract: sequencer,
    filter: sequencer.filters.SequencerBatchDelivered(batch),
    fromBlock: fromBlockEth,
    toBlock: await sequencer.provider.getBlockNumber(),
  });
  if (!emittedEvent) {
    return undefined;
  }

  const L1Block = (await emittedEvent.getBlock()) as Block;
  return [L1Block, L2BlockNumberFallback];
};

/**
 * This function finds the latest L2 batch and block number that has a corresponding batch on L1.
 *
 * @param nodeInterface Arbitrum NodeInterface
 * @param fromArbBlock from block number on Arb
 * @param latestBlockNumber latest block number on Arb
 *
 * @returns [latest L2 batch number, latest L2 block number]
 */

const findLatestL2BatchAndBlock = async (
  nodeInterface: NodeInterface,
  fromArbBlock: number,
  latestBlockNumber: number
): Promise<[number, number]> => {
  let low = fromArbBlock;
  let high = latestBlockNumber;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    try {
      (await nodeInterface.functions.findBatchContainingBlock(mid)) as any;
      low = mid + 1;
    } catch (e) {
      high = mid - 1;
    }
  }

  // high is now the latest L2 block number that has a corresponding batch on L1
  const result = (await nodeInterface.functions.findBatchContainingBlock(high)) as any;
  return [result.batch.toNumber(), high];
};

export { getBlocksAndCheckFinality, getSequencerDelaySeconds };

import { ClaimStruct } from "../../../contracts/typechain-types/arbitrumToEth/VeaInboxArbToEth";
import { JsonRpcProvider } from "@ethersproject/providers";
import { ethers } from "ethers";
import { ClaimNotFoundError } from "./errors";
import { getMessageStatus } from "./arbMsgExecutor";
import {
  getClaimForEpoch,
  getChallengerForClaim,
  getVerificationForClaim,
  getSnapshotSentForEpoch,
} from "./graphQueries";
import { defaultEmitter } from "../utils/emitter";
import { BotEvents } from "./botEvents";
import { Network } from "../consts/bridgeRoutes";
import { blockAtTimestamp } from "./epochHandler";
import { scanLogs, findFirstLog, findLatestLog } from "./logScanner";

enum ClaimHonestState {
  NONE = 0,
  CLAIMER = 1,
  CHALLENGER = 2,
}

export interface ClaimParams {
  network: Network;
  chainId: number;
  veaOutbox: any;
  veaOutboxProvider: JsonRpcProvider;
  epoch: number;
  epochPeriod: number;
  emitter: typeof defaultEmitter;
  fetchClaimForEpoch?: typeof getClaimForEpoch;
  fetchVerificationForClaim?: typeof getVerificationForClaim;
  fetchChallengerForClaim?: typeof getChallengerForClaim;
}

/**
 * Block-time estimates and epoch boundaries are both approximate, so the claim
 * window is padded outward at both ends. Missing the block a claim was made in
 * is an unchallenged-fraud failure; scanning a few hundred extra blocks costs
 * at most one extra chunk.
 */
const CLAIM_WINDOW_PAD_BLOCKS = 256;

const emptyClaim = (): ClaimStruct => ({
  stateRoot: ethers.ZeroHash,
  claimer: ethers.ZeroAddress,
  timestampClaimed: 0,
  timestampVerification: 0,
  blocknumberVerification: 0,
  honest: 0,
  challenger: ethers.ZeroAddress,
});

/**
 * Reconstruct the claim for an epoch from the outbox's own logs.
 *
 * Both outboxes require `_epoch == block.timestamp / epochPeriod - 1` inside
 * `claim()`, so a claim for epoch E can only have been made during
 * `[(E+1)*P, (E+2)*P)`. That is a hard bound, and scanning all of it is what
 * closes the detection gap: anchoring at `E*P` and clamping to a fixed block
 * count left the tail of the window unscanned.
 *
 * Reconstruction escalates. The cheapest candidate - an unchallenged, unverified
 * claim - is tried against the on-chain claim hash first, and only if that fails
 * do we pay to scan for `Challenged` and `VerificationStarted`, which cannot
 * have been emitted before the claim itself existed.
 *
 * @returns The reconstructed claim, or null if the logs could not produce one
 */
const reconstructClaimFromLogs = async (
  { veaOutbox, veaOutboxProvider, epoch, epochPeriod, emitter }: ClaimParams,
  claimHash: string,
  headBlock: { number: number }
): Promise<ClaimStruct | null> => {
  try {
    const [windowStart, windowEnd] = await Promise.all([
      blockAtTimestamp({ provider: veaOutboxProvider, timestamp: (epoch + 1) * epochPeriod }),
      blockAtTimestamp({ provider: veaOutboxProvider, timestamp: (epoch + 2) * epochPeriod }),
    ]);
    const fromBlock = Math.max(windowStart - CLAIM_WINDOW_PAD_BLOCKS, 0);
    const toBlock = Math.min(windowEnd + CLAIM_WINDOW_PAD_BLOCKS, headBlock.number);

    // At most one `Claimed` can exist per epoch: `claim()` requires
    // `claimHashes[_epoch] == 0`, so the first hit is the only hit.
    const claimedLog = await findFirstLog({
      contract: veaOutbox,
      filter: veaOutbox.filters.Claimed(null, epoch, null),
      fromBlock,
      toBlock,
    });
    if (!claimedLog) {
      // The claim hash is non-zero, so a claim provably exists but our scan did
      // not see it. Distinct from an RPC failure, and worth its own log line.
      emitter.emit(BotEvents.CLAIMED_LOG_NOT_FOUND, epoch, fromBlock, toBlock);
      return null;
    }

    const claim = emptyClaim();
    claim.stateRoot = claimedLog.data;
    claim.claimer = `0x${claimedLog.topics[1].slice(26)}`;
    claim.timestampClaimed = (await veaOutboxProvider.getBlock(claimedLog.blockNumber)).timestamp;

    const verified = verifyClaimHash({ claim, claimHash });
    if (verified) return verified;

    const [challengeLogs, verificationLogs] = await Promise.all([
      scanLogs({
        contract: veaOutbox,
        filter: veaOutbox.filters.Challenged(epoch, null),
        fromBlock: claimedLog.blockNumber,
        toBlock: headBlock.number,
      }),
      scanLogs({
        contract: veaOutbox,
        filter: veaOutbox.filters.VerificationStarted(epoch),
        fromBlock: claimedLog.blockNumber,
        toBlock: headBlock.number,
      }),
    ]);
    if (verificationLogs.length > 0) {
      claim.blocknumberVerification = verificationLogs[0].blockNumber;
      claim.timestampVerification = (await veaOutboxProvider.getBlock(verificationLogs[0].blockNumber)).timestamp;
    }
    if (challengeLogs.length > 0) claim.challenger = "0x" + challengeLogs[0].topics[2].substring(26);
    return claim;
  } catch (error) {
    emitter.emit(BotEvents.CLAIM_LOG_SCAN_FAILED, epoch, (error as Error)?.message);
    return null;
  }
};

/**
 * Reconstruct the claim for an epoch from the indexer.
 *
 * The result is only ever trusted after `verifyClaimHash` checks it against the
 * on-chain claim hash, so a wrong answer here cannot produce a wrong decision -
 * only an inability to act.
 *
 * @returns The reconstructed claim, or null if the indexer has no claim
 */
const reconstructClaimFromGraph = async ({
  chainId,
  veaOutbox,
  veaOutboxProvider,
  epoch,
  fetchClaimForEpoch = getClaimForEpoch,
}: ClaimParams): Promise<ClaimStruct | null> => {
  const claimFromGraph = await fetchClaimForEpoch(epoch, await veaOutbox.getAddress(), chainId);
  if (!claimFromGraph) return null;

  const claim = emptyClaim();
  claim.stateRoot = claimFromGraph.stateRoot;
  claim.claimer = claimFromGraph.bridger;
  claim.timestampClaimed = claimFromGraph.timestamp;
  if (claimFromGraph.verification?.[0]?.startTimestamp) {
    claim.timestampVerification = claimFromGraph.verification[0].startTimestamp;
    const txReceipt = await veaOutboxProvider.getTransactionReceipt(claimFromGraph.verification[0].startTxHash);
    claim.blocknumberVerification = txReceipt.blockNumber;
  }
  if (claimFromGraph.challenge?.[0]) claim.challenger = claimFromGraph.challenge[0].challenger;
  return claim;
};

/**
 * Fetch the claim for an epoch, reconstructing it from logs where possible and
 * from the indexer otherwise. Either source is only accepted once it hashes to
 * the outbox's own `claimHashes[epoch]`.
 *
 * @param veaOutbox VeaOutbox contract instance
 * @param epoch epoch number of the claim to be fetched
 * @returns claim type of ClaimStruct, or null if no claim was made for the epoch
 */
const getClaim = async (params: ClaimParams): Promise<ClaimStruct | null> => {
  const { veaOutbox, veaOutboxProvider, epoch, emitter } = params;
  // The claim hash and the logs it is reconstructed from must be read at the
  // same block. Reading the hash at the head while scanning logs only up to
  // finalized makes reconstruction fail whenever an event lands in between.
  const headBlock = await veaOutboxProvider.getBlock("finalized");
  const claimHash = await veaOutbox.claimHashes(epoch, { blockTag: headBlock.number });
  if (claimHash === ethers.ZeroHash) return null;

  const claimFromLogs = await reconstructClaimFromLogs(params, claimHash, headBlock);
  const verifiedFromLogs = claimFromLogs && verifyClaimHash({ claim: claimFromLogs, claimHash });
  if (verifiedFromLogs) return verifiedFromLogs;

  const claimFromGraph = await reconstructClaimFromGraph(params);
  // Verify that this branch is never reached for an epoch where no claim was made
  if (!claimFromGraph) {
    emitter.emit(BotEvents.NO_CLAIM_FETCHED, epoch);
    throw new ClaimNotFoundError(epoch);
  }
  const verifiedFromGraph = verifyClaimHash({ claim: claimFromGraph, claimHash });
  if (verifiedFromGraph) return verifiedFromGraph;

  emitter.emit(BotEvents.CLAIM_MISMATCH, epoch);
  throw new ClaimNotFoundError(epoch);
};

type ClaimResolveState = {
  sendSnapshot: {
    status: boolean;
    txHash: string;
  };
  execution: {
    status: number; // 0: not ready, 1: ready, 2: executed
    txHash: string;
  };
};

export interface ClaimResolveStateParams {
  chainId: number;
  veaInbox: any;
  veaInboxProvider: JsonRpcProvider;
  veaOutbox: any;
  // The actual outbox chain's provider (e.g. Chiado for arbToGnosis), used to
  // read the outbox contract's own head and claimHashes at that height.
  veaOutboxProvider: JsonRpcProvider;
  // L1/router provider. Arbitrum's child-to-parent messages always resolve
  // against L1 regardless of where the outbox lives, so this (not
  // veaOutboxProvider) is what fetchMessageStatus needs. Defaults to
  // veaOutboxProvider for routes where the outbox lives on L1 (arbToEth).
  veaRouterProvider?: JsonRpcProvider;
  epoch: number;
  epochPeriod: number;
  headBlockTag?: "latest" | "finalized";
  fetchMessageStatus?: typeof getMessageStatus;
  fetchSentSnapshotData?: typeof getSentSnapshotData;
}

/**
 * Fetches the claim resolve state. Verifies claimHash from sent snapshot logs with Outbox claimHash. To call if claim is not yet resolved else an extra snapshot will be sent.
 * @param veaInbox VeaInbox contract instance
 * @param veaInboxProvider VeaInbox provider
 * @param veaOutbox VeaOutbox contract instance
 * @param veaOutboxProvider VeaOutbox provider
 * @param epoch epoch number of the claim to be fetched
 * @param fromBlock from block number
 * @param toBlock to block number
 * @param fetchMessageStatus function to fetch message status
 * @returns ClaimResolveState
 **/
const getClaimResolveState = async ({
  chainId,
  veaInbox,
  veaInboxProvider,
  veaOutbox,
  veaOutboxProvider,
  veaRouterProvider,
  epoch,
  epochPeriod,
  headBlockTag = "finalized",
  fetchMessageStatus = getMessageStatus,
  fetchSentSnapshotData = getSentSnapshotData,
}: ClaimResolveStateParams): Promise<ClaimResolveState> => {
  let claimResolveState: ClaimResolveState = {
    sendSnapshot: {
      status: false,
      txHash: "",
    },
    execution: {
      status: 0,
      txHash: "",
    },
  };
  const outboxHeadBlock = await veaOutboxProvider.getBlock(headBlockTag);
  try {
    // SnapshotSent is emitted on the inbox chain, so its range must be expressed
    // in inbox block numbers. `sendSnapshot` requires
    // `_epoch < block.timestamp / epochPeriod`, so nothing can have been sent for
    // this epoch before (E+1)*P on the inbox clock.
    const inboxHeadBlock = await veaInboxProvider.getBlock(headBlockTag);
    const earliestSendBlock = await blockAtTimestamp({
      provider: veaInboxProvider,
      timestamp: (epoch + 1) * epochPeriod,
      headBlockTag,
    });
    const latestSnapshotSent = await findLatestLog({
      contract: veaInbox,
      filter: veaInbox.filters.SnapshotSent(epoch, null),
      fromBlock: Math.max(earliestSendBlock - CLAIM_WINDOW_PAD_BLOCKS, 0),
      toBlock: inboxHeadBlock.number,
    });
    if (latestSnapshotSent) {
      const sentSnapshotLogs = [latestSnapshotSent];
      // Add logic to check if the sent message has the actual claimHash or not
      const expectedClaimHash = await fetchSentSnapshotData(
        sentSnapshotLogs[0].transactionHash,
        veaInboxProvider,
        veaInbox.interface
      );
      const claimHash = await veaOutbox.claimHashes(epoch, { blockTag: outboxHeadBlock.number });

      if (claimHash === expectedClaimHash) {
        claimResolveState.sendSnapshot.status = true;
        claimResolveState.sendSnapshot.txHash = sentSnapshotLogs[0].transactionHash;
      } else {
        return claimResolveState;
      }
    } else {
      return claimResolveState;
    }
  } catch {
    const sentSnapshotFromGraph = await getSnapshotSentForEpoch(epoch, await veaInbox.getAddress(), chainId);
    if (sentSnapshotFromGraph) {
      const expectedClaimHash = await fetchSentSnapshotData(
        sentSnapshotFromGraph.txHash,
        veaInboxProvider,
        veaInbox.interface
      );
      const claimHash = await veaOutbox.claimHashes(epoch, { blockTag: outboxHeadBlock.number });
      if (claimHash === expectedClaimHash) {
        claimResolveState.sendSnapshot.status = true;
        claimResolveState.sendSnapshot.txHash = sentSnapshotFromGraph.txHash;
      } else {
        return claimResolveState;
      }
    } else {
      return claimResolveState;
    }
  }

  const status = await fetchMessageStatus(
    claimResolveState.sendSnapshot.txHash,
    veaInboxProvider,
    veaRouterProvider ?? veaOutboxProvider
  );
  claimResolveState.execution.status = status;

  return claimResolveState;
};

/**
 * Check a reconstructed claim against the outbox's own claim hash.
 *
 * `honest` is not carried by any event, so it is recovered by trying each of the
 * three possible values. The *matching variant* is returned rather than a
 * boolean: the caller needs the struct that actually hashes to `claimHash`,
 * since every contract call taking a claim re-hashes it and reverts on mismatch.
 *
 * @returns The claim variant that hashes to `claimHash`, or null if none does
 */
const verifyClaimHash = ({ claim, claimHash }: { claim: ClaimStruct; claimHash: string }): ClaimStruct | null => {
  const candidates: ClaimStruct[] = [
    { ...claim, honest: ClaimHonestState.NONE },
    { ...claim, honest: ClaimHonestState.CLAIMER },
    { ...claim, honest: ClaimHonestState.CHALLENGER },
  ];
  return candidates.find((candidate) => hashClaim(candidate) === claimHash) ?? null;
};

/**
 * Hashes the claim data.
 *
 * @param claim - The claim data to be hashed
 *
 * @returns The hash of the claim data
 *
 */
const hashClaim = (claim: ClaimStruct) => {
  return ethers.solidityPackedKeccak256(
    ["bytes32", "address", "uint32", "uint32", "uint32", "uint8", "address"],
    [
      claim.stateRoot,
      claim.claimer,
      claim.timestampClaimed,
      claim.timestampVerification,
      claim.blocknumberVerification,
      claim.honest,
      claim.challenger,
    ]
  );
};

const getSentSnapshotData = async (
  txHash: string,
  provider: JsonRpcProvider,
  inboxInterface: any
): Promise<string | null> => {
  const tx = await provider.getTransaction(txHash);
  if (!tx) return null;

  // Parse the transaction calldata to identify function + args
  const parsed = inboxInterface.parseTransaction({ data: tx.data });
  const args = parsed.args;
  const claimTuple = args[1] as ClaimStruct;
  const expectedClaimHash = hashClaim(claimTuple);
  return expectedClaimHash;
};

export { getClaim, hashClaim, getClaimResolveState, ClaimHonestState };

import { getBridgeConfig, Network } from "./consts/bridgeRoutes";
import { getVeaInbox, getVeaOutbox } from "./utils/ethers";
import { FallbackRpcProvider } from "./utils/fallbackProvider";
import { FallbackProviderV5 } from "./utils/fallbackProviderV5";
import { setEpochRange } from "./utils/epochHandler";
import { defaultEmitter } from "./utils/emitter";
import { BotEvents } from "./utils/botEvents";
import { initialize as initializeLogger } from "./utils/logger";
import { ShutdownSignal } from "./utils/shutdown";
import { getBotPath, BotPaths, getNetworkConfig, NetworkConfig } from "./utils/botConfig";
import { getClaim } from "./utils/claim";
import { CheckAndClaimParams, checkAndClaim } from "./helpers/claimer";
import { ChallengeAndResolveClaimParams, challengeAndResolveClaim } from "./helpers/validator";
import { saveSnapshot, SaveSnapshotParams } from "./helpers/snapshot";
import { getTransactionHandler } from "./utils/transactionHandlers";
import { validateEnvironment } from "./utils/envValidation";

const CYCLE_DELAY_MS = 2 * 60 * 1000; // 2 minutes

/**
 * @file This file contains the logic for watching bridge and validating/resolving for claims.
 *
 * @param shutDownSignal - The signal to shut down the watcher
 * @param emitter - The emitter to emit events
 *
 */

export const watch = async (
  shutDownSignal: ShutdownSignal = new ShutdownSignal(),
  emitter: typeof defaultEmitter = defaultEmitter
) => {
  initializeLogger(emitter);
  // Validate the whole environment before anything else, including before the
  // first heartbeat: a bot that reports "started" and then dies on a missing
  // variable looks alive to whatever is watching it.
  const validatedEnv = await validateEnvironment();
  emitter.emit(BotEvents.ENV_VALIDATED, validatedEnv.signerAddress, validatedEnv.chainIds, validatedEnv.networks);
  for (const warning of validatedEnv.warnings) emitter.emit(BotEvents.ENV_WARNING, warning);
  const cliCommand = process.argv;
  const { path, toSaveSnapshot } = getBotPath({ cliCommand });
  const networkConfigs = getNetworkConfig();
  emitter.emit(BotEvents.STARTED, path, networkConfigs[0].networks);
  const transactionHandlers: { [key: string]: any } = {};
  const toWatch: { [key: string]: { count: number; epochs: number[] } } = {};
  while (!shutDownSignal.getIsShutdownSignal()) {
    for (const networkConfig of networkConfigs) {
      await processNetwork(path, toSaveSnapshot, networkConfig, transactionHandlers, toWatch, emitter);
    }
    await wait(CYCLE_DELAY_MS);
  }
};

async function processNetwork(
  path: number,
  toSaveSnapshot: boolean,
  networkConfig: NetworkConfig,
  transactionHandlers: { [key: string]: any },
  toWatch: { [key: string]: { count: number; epochs: number[] } },
  emitter: typeof defaultEmitter
): Promise<void> {
  const { chainId, networks } = networkConfig;
  const { routeConfig, inboxRPC, outboxRPC, routerRPC } = getBridgeConfig(chainId);
  for (const network of networks) {
    emitter.emit(BotEvents.WATCHING, chainId, network);
    const networkKey = `${chainId}_${network}`;
    if (!toWatch[networkKey]) {
      toWatch[networkKey] = { count: -1, epochs: [] };
    }
    const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
    let veaOutboxLatestBlock = await veaOutboxProvider.getBlock("latest");

    // If the watcher has already started, only check the latest epoch
    if (network == Network.DEVNET) {
      toWatch[networkKey].epochs = [Math.floor(veaOutboxLatestBlock.timestamp / routeConfig[network].epochPeriod)];
    } else if (toWatch[networkKey].epochs.length == 0) {
      const epochRange = setEpochRange({
        chainId,
        currentTimestamp: veaOutboxLatestBlock.timestamp,
        epochPeriod: routeConfig[network].epochPeriod,
      });
      toWatch[networkKey].epochs = epochRange;
    }

    await processEpochsForNetwork({
      chainId,
      path,
      toSaveSnapshot,
      networkKey,
      network,
      routeConfig,
      inboxRPC,
      outboxRPC,
      routerRPC,
      toWatch,
      transactionHandlers,
      emitter,
    });
    const currentLatestBlock = await veaOutboxProvider.getBlock("latest");
    const currentClaimableEpoch = Math.floor(currentLatestBlock.timestamp / routeConfig[network].epochPeriod) - 1;

    const toWatchEpochs = toWatch[networkKey];
    const lastEpochInToWatch = toWatchEpochs[toWatchEpochs.epochs.length - 1];
    if (currentClaimableEpoch > lastEpochInToWatch) {
      toWatch[networkKey].epochs.push(currentClaimableEpoch);
    }
  }
}

interface ProcessEpochParams {
  chainId: number;
  path: number;
  toSaveSnapshot: boolean;
  networkKey: string;
  network: Network;
  routeConfig: any;
  inboxRPC: string[];
  outboxRPC: string[];
  routerRPC: string[] | undefined;
  toWatch: { [key: string]: { count: number; epochs: number[] } };
  transactionHandlers: { [key: string]: any };
  emitter: typeof defaultEmitter;
}
async function processEpochsForNetwork({
  chainId,
  path,
  toSaveSnapshot,
  networkKey,
  network,
  routeConfig,
  inboxRPC,
  outboxRPC,
  routerRPC,
  toWatch,
  transactionHandlers,
  emitter,
}: ProcessEpochParams) {
  const privKey = process.env.PRIVATE_KEY;
  // v6 providers for the typechain contract connections (the inbox chainId is detected via the fallback transport).
  const veaInboxContractProvider = new FallbackRpcProvider(inboxRPC, emitter);
  const veaOutboxContractProvider = new FallbackRpcProvider(outboxRPC, emitter, chainId);
  const veaInbox = getVeaInbox(
    routeConfig[network].veaInbox.address,
    privKey,
    veaInboxContractProvider,
    chainId,
    network
  );
  const veaOutbox = getVeaOutbox(
    routeConfig[network].veaOutbox.address,
    privKey,
    veaOutboxContractProvider,
    chainId,
    network
  );
  // v5 providers for the standalone reads / Arbitrum SDK path.
  const veaInboxProvider = new FallbackProviderV5(inboxRPC, emitter);
  const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
  const veaRouterProvider = routerRPC && routerRPC.length > 0 ? new FallbackProviderV5(routerRPC, emitter) : undefined;
  let i = toWatch[networkKey].epochs.length - 1;
  let latestEpoch = toWatch[networkKey].epochs[i];
  const currentEpoch = Math.floor(Date.now() / (1000 * routeConfig[network].epochPeriod));
  if (latestEpoch != currentEpoch - 1 && network != Network.DEVNET) {
    toWatch[networkKey].epochs.push(currentEpoch - 1);
    latestEpoch = currentEpoch - 1;
    i++;
  }
  // Checks and saves the snapshot if needed
  if (toSaveSnapshot) {
    const TransactionHandler = getTransactionHandler(chainId, network) as any;
    const txnHandlerKey = `${routeConfig[network].veaInbox.address}_${currentEpoch}`;
    const transactionHandler =
      transactionHandlers[currentEpoch] ||
      new TransactionHandler({
        network,
        epoch: currentEpoch,
        veaInbox,
        veaOutbox,
        veaInboxProvider,
        veaOutboxProvider,
        veaRouterProvider,
        emitter,
      });
    const { updatedTransactionHandler, latestCount } = await saveSnapshot({
      chainId,
      veaInbox,
      veaOutbox,
      veaInboxProvider,
      veaOutboxProvider,
      network,
      epochPeriod: routeConfig[network].epochPeriod,
      count: toWatch[networkKey].count,
      transactionHandler,
    } as SaveSnapshotParams);
    const count = toWatch[networkKey].count;
    if (count == -1 || count != latestCount) {
      transactionHandlers[txnHandlerKey] = updatedTransactionHandler;
      toWatch[networkKey].count = latestCount;
    }
  }

  while (i >= 0) {
    const epoch = toWatch[networkKey].epochs[i];
    const claim = await getClaim({
      network,
      chainId,
      veaOutbox,
      veaOutboxProvider,
      epoch,
      epochPeriod: routeConfig[network].epochPeriod,
      emitter,
    });

    let updatedTransactions;
    if (path > BotPaths.CLAIMER && claim != null) {
      const checkAndChallengeResolveDeps: ChallengeAndResolveClaimParams = {
        chainId,
        claim,
        epoch,
        epochPeriod: routeConfig[network].epochPeriod,
        veaInbox,
        veaInboxProvider,
        veaOutboxProvider,
        veaRouterProvider,
        veaOutbox,
        transactionHandler: transactionHandlers[epoch],
        emitter,
      };
      updatedTransactions = await challengeAndResolveClaim(checkAndChallengeResolveDeps);
    }
    if (path == BotPaths.CLAIMER || path == BotPaths.BOTH) {
      const checkAndClaimParams: CheckAndClaimParams = {
        network,
        chainId,
        claim,
        epoch,
        epochPeriod: routeConfig[network].epochPeriod,
        veaInbox,
        veaInboxProvider,
        veaOutboxProvider,
        veaRouterProvider,
        veaOutbox,
        transactionHandler: transactionHandlers[epoch],
        emitter,
      };
      updatedTransactions = await checkAndClaim(checkAndClaimParams);
    }

    if (updatedTransactions) {
      transactionHandlers[epoch] = updatedTransactions;
    } else if (epoch != currentEpoch - 1 && epoch != latestEpoch) {
      delete transactionHandlers[epoch];
      toWatch[networkKey].epochs.splice(i, 1);
    }
    i--;
  }
}

const wait = (ms: number): Promise<void> => new Promise((resolve: () => void) => setTimeout(resolve, ms));

if (require.main === module) {
  const shutDownSignal = new ShutdownSignal(false);
  watch(shutDownSignal);
}

